<script setup>import{watch,nextTick,onBeforeUnmount}from'vue';const p=defineProps({modelValue:Boolean,title:String,size:{type:String,default:'md'},closeOnOverlay:{type:Boolean,default:true},closeOnEsc:{type:Boolean,default:true}}),e=defineEmits(['update:modelValue','close']);let old=null,overflow='';function close(){e('update:modelValue',false);e('close')}function key(x){if(x.key==='Escape'&&p.closeOnEsc)close();if(x.key==='Tab'){const a=[...document.querySelectorAll('[data-modal] button,[data-modal] input')];if(x.shiftKey&&document.activeElement===a[0]){x.preventDefault();a.at(-1)?.focus()}else if(!x.shiftKey&&document.activeElement===a.at(-1)){x.preventDefault();a[0]?.focus()}}}watch(()=>p.modelValue,async v=>{if(v){old=document.activeElement;overflow=document.body.style.overflow;document.body.style.overflow='hidden';window.addEventListener('keydown',key);await nextTick();document.querySelector('[data-modal]')?.querySelector('button,input')?.focus()}else{window.removeEventListener('keydown',key);document.body.style.overflow=overflow;old?.isConnected&&old.focus()}});onBeforeUnmount(()=>{window.removeEventListener('keydown',key);document.body.style.overflow=overflow})</script><template><Teleport to="body"><div v-if="modelValue" class="overlay" @mousedown.self="closeOnOverlay&&close()"><section class="panel" :class="size" role="dialog" aria-modal="true" :aria-label="title||'对话框'" data-modal tabindex="-1"><header v-if="title||$slots.header"><slot name="header"><h2>{{title}}</h2></slot><button aria-label="关闭" @click="close">×</button></header><main><slot/></main><footer v-if="$slots.footer"><slot name="footer" :close="close"/></footer></section></div></Teleport></template><style scoped>.overlay{position:fixed;inset:0;z-index:var(--z-modal,60);display:grid;place-items:center;padding:16px;background:#11182799}.panel{width:100%;max-height:90vh;overflow:auto;background:var(--surface);color:var(--text);border:1px solid var(--line);border-radius:var(--radius-xl);box-shadow:v